prompt --application/shared_components/logic/application_processes/get_notifications
begin
wwv_flow_imp_shared.create_flow_process(
 p_id=>wwv_flow_imp.id(156013355612654008342)
,p_process_sequence=>1
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'GET_NOTIFICATIONS'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_html clob;',
'begin',
'    l_html := '''';',
'',
'    for r in (',
'        select',
'            notification_id,',
'            notification_title,',
'            notification_body,',
'            target_url,',
'            is_read,',
'            created_at',
'        from app_notifications',
'        where upper(user_name) = upper(:APP_USER)',
'        order by created_at desc',
'        fetch first 5 rows only',
'    ) loop',
'        l_html := l_html ||',
'            ''<div class="notif-item" data-id="'' || r.notification_id || ''">'' ||',
'                ''<div class="notif-item-main">'' ||',
'                    ''<div class="notif-item-title">'' ||',
'                        apex_escape.html(r.notification_title) ||',
'                    ''</div>'' ||',
'                    ''<div class="notif-item-body">'' ||',
'                        apex_escape.html(r.notification_body) ||',
'                    ''</div>'' ||',
'                ''</div>'' ||',
'                ''<div class="notif-item-actions">'' ||',
'                    case',
'                        when r.is_read = ''N'' then',
'                            ''<button type="button" class="t-Button t-Button--tiny t-Button--simple js-mark-read">Mark as read</button>''',
'                        else',
'                            ''<span class="notif-item-read">Read</span>''',
'                    end ||',
'                ''</div>'' ||',
'            ''</div>'';',
'    end loop;',
'',
'    if l_html is null then',
'        l_html := ''<div class="notif-item"><div class="notif-item-body">No notifications found.</div></div>'';',
'    end if;',
'',
'    htp.p(l_html);',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_security_scheme=>'MUST_NOT_BE_PUBLIC_USER'
,p_version_scn=>15754159954245
);
end;
/
prompt --application/shared_components/logic/application_processes/mark_notification_read
begin
wwv_flow_imp_shared.create_flow_process(
 p_id=>wwv_flow_imp.id(156017003892854671451)
,p_process_sequence=>1
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'MARK_NOTIFICATION_READ'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_notification_id number := to_number(apex_application.g_x01);',
'begin',
'    update app_notifications',
'       set is_read = ''Y'',',
'           read_at = systimestamp',
'     where notification_id = l_notification_id',
'       and upper(user_name) = upper(:APP_USER);',
'',
'    commit;',
'',
'    htp.p(''OK'');',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_security_scheme=>'MUST_NOT_BE_PUBLIC_USER'
,p_version_scn=>15754160420072
);
end;
/
prompt --application/shared_components/logic/application_processes/refresh_unread_notifications
begin
wwv_flow_imp_shared.create_flow_process(
 p_id=>wwv_flow_imp.id(156017752745249048215)
,p_process_sequence=>1
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'REFRESH_UNREAD_NOTIFICATIONS'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'begin',
'    select nullif(count(*), 0)',
'      into :UNREAD_NOTIFICATIONS',
'      from app_notifications',
'     where upper(user_name) = upper(:APP_USER)',
'       and is_read = ''N'';',
'',
'    htp.p(nvl(:UNREAD_NOTIFICATIONS, ''''));',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_security_scheme=>'MUST_NOT_BE_PUBLIC_USER'
,p_version_scn=>15754160977100
);
end;
